import java.util.Scanner;

public class Main {
    static final long MOD = 1000000007L;

    // modular exponentiation: base^exp % mod
    static long modPow(long base, long exp, long mod) {
        long result = 1;
        base %= mod;
        while (exp > 0) {
            if ((exp & 1) == 1) {
                result = (result * base) % mod;
            }
            base = (base * base) % mod;
            exp >>= 1;
        }
        return result;
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int P = sc.nextInt();
        int K = sc.nextInt();
        sc.close();

        // special cases K = 0 or 1
        if (K == 0) {
            System.out.println(modPow(P, P - 1, MOD));
            return;
        }
        if (K == 1) {
            System.out.println(modPow(P, P, MOD));
            return;
        }

        boolean[] visited = new boolean[P];
        int[] cycleCounts = new int[P + 1]; // index = component size

        // traverse the functional graph defined by f(x) = (K * x) % P
        for (int start = 0; start < P; start++) {
            if (visited[start]) continue;
            int node = start;
            int clen = 0;
            while (!visited[node]) {
                visited[node] = true;
                node = (int)(((long)K * node) % P);
                clen++;
            }
            cycleCounts[clen]++;
        }

        long ans = 1;
        for (int i = 2; i < P; i++) {
            int c = cycleCounts[i];
            if (c > 0) {
                long base = (long)i * c + 1;
                base %= MOD;
                ans = ans * modPow(base, c, MOD) % MOD;
            }
        }
        System.out.println(ans);
    }
}
